mapper.select:
SELECT t1.id as recordId, t1.name as name, t1.code as code, t1.category_id as categoryId, t2.id as versionId, t2.remark as remark, t2.version as version, t2.state as state, t2.instance_id as instanceId, t2.create_by as createBy, t2.effective_time as effectiveTime FROM bm_batch_record AS t1 JOIN bm_batch_record_version AS t2 ON t1.id = t2.record_id where t1.is_deleted = 0 and t2.is_deleted = 0
and t1.name like concat('%',#{name},'%')
and t1.category_id =#{categoryId}
and t2.state = #{recordState}
and t2.record_id =#{recordId} order by t2.create_time desc

SELECT DISTINCT t1.id as id, t1.name as name FROM bm_batch_record AS t1 join lm_resource_permission t2 on t1.id = t2.resource_id where t1.is_deleted = 0 and t2.dept_id in
#{item}
and t1.id in
#{item}
